#include "models/PollPost.h"
#include <algorithm>
#include <cstdint>
#include <istream>
#include <ostream>
#include <stdexcept>
using namespace std;
static void poll_put(ostream& o,const string& s){if(s.size()>1000000)throw runtime_error("Text too long");uint32_t n=static_cast<uint32_t>(s.size());o.write(reinterpret_cast<const char*>(&n),4);o.write(s.data(),n);if(!o)throw runtime_error("Write failed");}
static string poll_get(istream& i){uint32_t n=0;i.read(reinterpret_cast<char*>(&n),4);if(!i||n>1000000)throw runtime_error("Bad text length");string s(n,'\0');if(n)i.read(&s[0],n);if(!i)throw runtime_error("Read failed");return s;}
PollPost::PollPost():Post(),question_(),options_(),option_voters_(),closed_(false){}
PollPost::PollPost(int a,const Time& t,const string& c,const string& q,const vector<string>& o):Post(a,t,c),question_(q),options_(o),option_voters_(o.size()),closed_(false){if(q.empty()||o.size()<2||o.size()>1000)throw invalid_argument("Invalid poll");for(const string& s:o)if(s.empty())throw invalid_argument("Empty option");}
string PollPost::type_name()const{return "Poll";} string PollPost::search_text()const{string s=caption()+" "+question_;for(const string& o:options_)s+=" "+o;return s;} float PollPost::render_height(float w)const{return w>0?80.0f+options_.size()*36.0f:0;}
void PollPost::draw(DrawContext& c,const Rectangle& r)const{(void)c;(void)r;}void PollPost::draw(DrawContext& c,float x,float y,float w)const{(void)c;(void)x;(void)y;(void)w;}
bool PollPost::handle_click(float mx,float my,float x,float y,float w,int v){(void)w;if(mx<x||mx>x+w||my<y+48)return false;int row=static_cast<int>((my-y-48)/36);return vote(v,row);}
const string& PollPost::question()const{return question_;}void PollPost::set_question(const string& q){question_=q;}int PollPost::option_count()const{return static_cast<int>(options_.size());}string PollPost::option_text(int i)const{return i<0||i>=option_count()?string():options_[i];}
int PollPost::vote_count(int i)const{return i<0||i>=option_count()?0:static_cast<int>(option_voters_[i].size());}int PollPost::total_votes()const{int n=0;for(const auto& v:option_voters_)n+=static_cast<int>(v.size());return n;}
bool PollPost::vote(int u,int i){if(closed_||u<=0||i<0||i>=option_count()||has_voted(u))return false;option_voters_[i].push_back(u);return true;}int PollPost::user_vote(int u)const{for(size_t i=0;i<option_voters_.size();++i)if(find(option_voters_[i].begin(),option_voters_[i].end(),u)!=option_voters_[i].end())return static_cast<int>(i);return -1;}bool PollPost::has_voted(int u)const{return user_vote(u)>=0;}bool PollPost::is_closed()const{return closed_;}void PollPost::set_closed(bool b){closed_=b;}
void PollPost::write(ostream& o)const{Post::write(o);poll_put(o,question_);uint8_t b=closed_;o.write(reinterpret_cast<const char*>(&b),1);uint32_t n=static_cast<uint32_t>(options_.size());o.write(reinterpret_cast<const char*>(&n),4);for(size_t j=0;j<options_.size();++j){poll_put(o,options_[j]);uint32_t m=static_cast<uint32_t>(option_voters_[j].size());o.write(reinterpret_cast<const char*>(&m),4);for(int u:option_voters_[j]){int32_t id=u;o.write(reinterpret_cast<const char*>(&id),4);}}if(!o)throw runtime_error("Write failed");}
void PollPost::read(istream& in){Post::read(in);string q=poll_get(in);uint8_t b=0;uint32_t n=0;in.read(reinterpret_cast<char*>(&b),1);in.read(reinterpret_cast<char*>(&n),4);if(!in||b>1||n>1000)throw runtime_error("Invalid poll");vector<string> opts;vector<vector<int>> voters;for(uint32_t j=0;j<n;++j){opts.push_back(poll_get(in));uint32_t m=0;in.read(reinterpret_cast<char*>(&m),4);if(!in||m>1000000)throw runtime_error("Invalid voter count");vector<int> vv;for(uint32_t k=0;k<m;++k){int32_t u=0;in.read(reinterpret_cast<char*>(&u),4);if(!in||u<=0||find(vv.begin(),vv.end(),u)!=vv.end())throw runtime_error("Invalid voter");for(const auto& prior:voters)if(find(prior.begin(),prior.end(),u)!=prior.end())throw runtime_error("Duplicate voter");vv.push_back(u);}voters.push_back(vv);}question_.swap(q);options_.swap(opts);option_voters_.swap(voters);closed_=b!=0;}
